#!/usr/bin/env python3
"""Synthetic Wayland surface. All recorded content is generated by the test."""
import json
import os
import time

import gi

gi.require_version("Gtk", "3.0")
gi.require_version("Gdk", "3.0")
from gi.repository import Gdk, GLib, Gtk

ROOT = os.environ["REMORA_VNC_ROOT"]
events = open(os.path.join(ROOT, "events.jsonl"), "a", buffering=1)


def record(kind, **values):
    events.write(json.dumps({"time": time.time(), "kind": kind, **values}, ensure_ascii=False) + "\n")


window = Gtk.Window(title="Remora synthetic VNC target")
window.set_default_size(1000, 650)
box = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=16)
box.set_border_width(24)
window.add(box)
box.pack_start(Gtk.Label(label="Remora VNC live test | synthetic content only"), False, False, 0)
entry = Gtk.Entry()
entry.set_placeholder_text("Keyboard target: ASCII, German umlauts, Unicode")
box.pack_start(entry, False, False, 0)
entry.connect("changed", lambda widget: record("text", text=widget.get_text()))
button = Gtk.Button(label="Click target / copy synthetic UTF-8")
box.pack_start(button, False, False, 0)
clipboard = Gtk.Clipboard.get(Gdk.SELECTION_CLIPBOARD)


def copy(_):
    clipboard.set_text("Remora clipboard: Grüße 日本語 🐟", -1)
    record("clipboard-offered")


button.connect("clicked", copy)
paste = Gtk.Button(label="Read client clipboard")
box.pack_start(paste, False, False, 0)
paste.connect("clicked", lambda _: clipboard.request_text(lambda _, text: record("clipboard-received", text=text)))
area = Gtk.DrawingArea()
area.set_size_request(800, 250)
area.add_events(Gdk.EventMask.POINTER_MOTION_MASK | Gdk.EventMask.BUTTON_PRESS_MASK |
                Gdk.EventMask.BUTTON_RELEASE_MASK | Gdk.EventMask.SCROLL_MASK |
                Gdk.EventMask.SMOOTH_SCROLL_MASK)
area.connect("motion-notify-event", lambda _, e: record("motion", x=e.x, y=e.y))
area.connect("button-press-event", lambda _, e: record("button-down", button=e.button, x=e.x, y=e.y))
area.connect("button-release-event", lambda _, e: record("button-up", button=e.button, x=e.x, y=e.y))
area.connect("scroll-event", lambda _, e: record("scroll", direction=int(e.direction), dx=e.delta_x, dy=e.delta_y))


def draw(_, cr):
    cr.set_source_rgb(0.07, 0.25, 0.36)
    cr.paint()
    cr.set_source_rgb(0.3, 0.85, 0.65)
    cr.rectangle(10 + (int(time.monotonic()) % 20) * 30, 60, 55, 55)
    cr.fill()
    cr.set_source_rgb(1, 1, 1)
    cr.set_font_size(22)
    cr.move_to(20, 38)
    cr.show_text("Pointer / wheel target; animated refresh marker")


area.connect("draw", draw)
area.connect("realize", lambda widget: widget.get_window().set_cursor(Gdk.Cursor.new_from_name(widget.get_display(), "crosshair")))
box.pack_start(area, True, True, 0)
window.connect("key-press-event", lambda _, e: record("key-down", keyval=e.keyval, hardware=e.hardware_keycode, state=int(e.state)))
window.connect("key-release-event", lambda _, e: record("key-up", keyval=e.keyval, hardware=e.hardware_keycode, state=int(e.state)))
window.connect("destroy", Gtk.main_quit)
GLib.timeout_add(500, lambda: (area.queue_draw(), True)[1])
window.show_all()
window.fullscreen()
entry.grab_focus()
record("ready")
Gtk.main()
